import sys


def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    best = 1
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):
            while l >= 0 and r < n and s[l] == s[r]:
                l -= 1
                r += 1
            if r - l - 1 > best:
                best = r - l - 1
    print(n - best)


